def transform(grid):
    """Complete either a wrapped diagonal tile or a vertically mirrored grid."""
    n = len(grid)
    period = [None] * n
    diagonal_ok = True
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                k = (c - r) % n
                if period[k] is not None and period[k] != value:
                    diagonal_ok = False
                else:
                    period[k] = value
    if diagonal_ok and all(v is not None for v in period):
        return [[period[(c-r) % n] for c in range(n)] for r in range(n)]

    # The other demonstrated form is a grid symmetric about its horizontal
    # centerline: copy each known row to its reflected partner.
    out = [row[:] for row in grid]
    for r in range(n):
        rr = n - 1 - r
        for c in range(n):
            if out[r][c] == 0 and out[rr][c] != 0:
                out[r][c] = out[rr][c]
            elif out[rr][c] == 0 and out[r][c] != 0:
                out[rr][c] = out[r][c]
    return out

def transform(grid):
    """Complete a cyclic diagonal tile, or mirror a solid-row pattern."""
    n = len(grid)

    # Solid horizontal bands use reflection across the horizontal midpoint.
    if all(len(set(row)) <= 1 for row in grid):
        out = [row[:] for row in grid]
        for r in range(n):
            rr = n - 1 - r
            for c in range(len(grid[r])):
                if out[r][c] == 0:
                    out[r][c] = out[rr][c]
        return out

    # The diagonal clues specify one of two wrapped diagonal tilings.
    candidates = []
    for sign in (-1, 1):
        period = [None] * n
        conflicts = 0
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value:
                    k = (c + sign * r) % n
                    if period[k] is not None and period[k] != value:
                        conflicts += 1
                    else:
                        period[k] = value
        candidates.append((conflicts, sum(v is None for v in period), sign, period))
    conflicts, missing, sign, period = min(candidates, key=lambda x: (x[0], x[1]))
    if conflicts or missing:
        raise ValueError("input does not determine a consistent diagonal tile")
    return [[period[(c + sign * r) % n] for c in range(len(row))]
            for r, row in enumerate(grid)]

def transform(grid):
    """Complete a repeated stripe sequence or a wrapped diagonal tile."""
    h = len(grid)
    w = len(grid[0])

    # Uniform horizontal rows encode a vertical color sequence. Repeat the
    # shortest period consistent with all nonzero rows.
    row_colors = []
    stripes = True
    for row in grid:
        colors = {v for v in row if v != 0}
        if len(colors) > 1:
            stripes = False
            break
        row_colors.append(next(iter(colors)) if colors else None)
    if stripes:
        for period in range(1, h + 1):
            known = [row_colors[r] for r in range(h) if row_colors[r] is not None]
            indices = [r for r in range(h) if row_colors[r] is not None]
            if all(known[i] == known[j] for i in range(len(indices))
                   for j in range(i) if (indices[i] - indices[j]) % period == 0):
                out = []
                for r in range(h):
                    color = row_colors[r]
                    if color is None:
                        # Get color from a known row in the same period class.
                        color = next(row_colors[q] for q in range(h)
                                     if row_colors[q] is not None and (q-r) % period == 0)
                    out.append([color] * w)
                return out

    # The non-stripe demonstrations encode a cyclic sequence along diagonals.
    n = h
    candidates = []
    for sign in (-1, 1):
        period = [None] * n
        conflicts = 0
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value:
                    k = (c + sign * r) % n
                    if period[k] is not None and period[k] != value:
                        conflicts += 1
                    else:
                        period[k] = value
        candidates.append((conflicts, sum(v is None for v in period), sign, period))
    conflicts, missing, sign, period = min(candidates, key=lambda x: (x[0], x[1]))
    if conflicts or missing:
        raise ValueError("input does not determine a consistent diagonal tile")
    return [[period[(c + sign * r) % n] for c in range(w)] for r in range(h)]

from collections import deque


def components(grid, color):
    h, w = len(grid), len(grid[0])
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
    out = []
    while unseen:
        start = unseen.pop()
        q = [start]
        comp = {start}
        while q:
            r, c = q.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in unseen:
                        unseen.remove(p)
                        comp.add(p)
                        q.append(p)
        out.append(comp)
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    fours = components(grid, 4)
    if not fours:
        return [row[:] for row in grid]
    # The color-4 object is the complete motif; normalize it to its top-left.
    motif_abs = max(fours, key=len)
    minr = min(r for r, c in motif_abs)
    minc = min(c for r, c in motif_abs)
    motif = {(r - minr, c - minc) for r, c in motif_abs}
    result = [row[:] for row in grid]

    for color in range(10):
        if color in (1, 4):
            continue
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        if not pts:
            continue
        candidates = set()
        for r, c in pts:
            for mr, mc in motif:
                ar, ac = r - mr, c - mc
                if all((pr - ar, pc - ac) in motif for pr, pc in pts):
                    candidates.add((ar, ac))
        if not candidates:
            continue
        # These fragments are portions of a translated copy of the motif.
        # In the demonstrated tasks the placement is uniquely determined.
        ar, ac = sorted(candidates)[0]
        for mr, mc in motif:
            rr, cc = ar + mr, ac + mc
            if 0 <= rr < h and 0 <= cc < w:
                result[rr][cc] = color
    return result

