def transform(grid):
    """Normalize the two palette colors by order: lower to 0, higher to 2."""
    colors = sorted({cell for row in grid for cell in row})
    mapping = {color: (0 if i == 0 else 2) for i, color in enumerate(colors)}
    return [[mapping[cell] for cell in row] for row in grid]

def transform(grid):
    """Replace color 5 with the other palette color, and that color with 0."""
    colors = {cell for row in grid for cell in row}
    if 5 not in colors or len(colors) != 2:
        raise ValueError("Expected color 5 and exactly one other color")
    other = next(color for color in colors if color != 5)
    return [[other if cell == 5 else 0 for cell in row] for row in grid]

def transform(grid):
    # Separators are the full rows/columns of color 5; each tile contains
    # background 2 with zero markers. Highlight the tile with two markers.
    sep = 5
    row_bounds = []
    start = 0
    for r, row in enumerate(grid):
        if all(v == sep for v in row):
            if start < r:
                row_bounds.append((start, r))
            start = r + 1
    if start < len(grid):
        row_bounds.append((start, len(grid)))

    width = len(grid[0])
    col_seps = [c for c in range(width) if all(grid[r][c] == sep for r in range(len(grid)))]
    col_bounds = []
    start = 0
    for c in col_seps:
        if start < c:
            col_bounds.append((start, c))
        start = c + 1
    if start < width:
        col_bounds.append((start, width))

    out = []
    for r0, r1 in row_bounds:
        out_row = []
        for c0, c1 in col_bounds:
            count = sum(grid[r][c] == 0 for r in range(r0, r1) for c in range(c0, c1))
            out_row.append(1 if count == 2 else 2)
        out.append(out_row)
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    # Extend all diagonal same-color pairs to the edges, retaining the original marks.
    from collections import defaultdict
    pts = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                pts[grid[r][c]].append((r,c))
    for color, cells in pts.items():
        for i, (r,c) in enumerate(cells):
            for rr, cc in cells[i+1:]:
                dr, dc = rr-r, cc-c
                if abs(dr) == abs(dc) and dr != 0:
                    sr, sc = (1 if dr>0 else -1), (1 if dc>0 else -1)
                    # Need an immediately adjacent diagonal pair.
                    if abs(dr) == 1:
                        x,y=r,c
                        while 0 <= x < h and 0 <= y < w:
                            if out[x][y] == bg: out[x][y] = color
                            x -= sr; y -= sc
                        x,y=rr,cc
                        while 0 <= x < h and 0 <= y < w:
                            if out[x][y] == bg: out[x][y] = color
                            x += sr; y += sc
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, defaultdict
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
