def transform(grid):
    """Expand diagonal marker tracks into their repeating color bands."""
    h, w = len(grid), len(grid[0])
    # The markers lie on parallel down-right diagonals, indexed by c-r.
    tracks = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                tracks.setdefault(c - r, set()).add(color)

    period = len(tracks)
    if period == 0 or any(len(colors) != 1 for colors in tracks.values()):
        return [row[:] for row in grid]

    # Each distinct marker track identifies one residue band. Tracks with the
    # same color identify same-colored bands; their offsets determine residues.
    palette = {}
    for offset, colors in tracks.items():
        residue = offset % period
        color = next(iter(colors))
        if residue in palette and palette[residue] != color:
            return [row[:] for row in grid]
        palette[residue] = color
    if len(palette) != period:
        return [row[:] for row in grid]

    return [[palette[(c - r) % period] for c in range(w)] for r in range(h)]

def transform(grid):
    """Repeat the colors of nonzero full-width horizontal marker rows by row residue."""
    h, w = len(grid), len(grid[0])
    markers = [(r, row[0]) for r, row in enumerate(grid)
               if row[0] != 0 and all(v == row[0] for v in row)]
    if not markers:
        return [row[:] for row in grid]
    period = len(markers)
    palette = {}
    for r, color in markers:
        residue = r % period
        if residue in palette and palette[residue] != color:
            return [row[:] for row in grid]
        palette[residue] = color
    if len(palette) != period:
        return [row[:] for row in grid]
    return [[palette[r % period]] * w for r in range(h)]

def transform(grid):
    """Complete colored stripes as a repeating one-dimensional pattern."""
    h, w = len(grid), len(grid[0])
    nonzero = [(r, c, v) for r, row in enumerate(grid)
               for c, v in enumerate(row) if v]
    if not nonzero:
        return [row[:] for row in grid]

    # The stripe may be horizontal, vertical, or diagonal. The input gives
    # repeated samples of its color word along one of these coordinates.
    coordinates = (
        (lambda r, c: r),
        (lambda r, c: c),
        (lambda r, c: r + c),
        (lambda r, c: c - r),
    )
    for coord in coordinates:
        known = {}
        consistent = True
        for r, c, color in nonzero:
            i = coord(r, c)
            if i in known and known[i] != color:
                consistent = False
                break
            known[i] = color
        if not consistent:
            continue

        # Find the shortest cyclic stripe word consistent with every sample;
        # require every position of that word to be anchored by the input.
        for period in range(1, len(known) + 1):
            residues = {}
            for i, color in known.items():
                k = i % period
                if k in residues and residues[k] != color:
                    break
                residues[k] = color
            else:
                if len(residues) == period:
                    return [[residues[coord(r, c) % period]
                             for c in range(w)] for r in range(h)]
    raise ValueError("could not infer a fully anchored periodic stripe pattern")

def transform(grid):
    """Tile the nonzero cells with 2x2 squares and L triominoes.

    A square is recolored 1. An L triomino is recolored by its missing
    corner in its 2x2 bounding box: TL=2, BL=3, TR=4, BR=5.
    """
    rows, cols = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(rows) for c in range(cols) if grid[r][c] != 0}
    placements = []
    for r in range(rows - 1):
        for c in range(cols - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            placements.append((block, 1))
            for missing, color in [
                ((r, c), 2),       # top-left
                ((r + 1, c), 3),   # bottom-left
                ((r, c + 1), 4),   # top-right
                ((r + 1, c + 1), 5),  # bottom-right
            ]:
                placements.append((block - {missing}, color))

    by_cell = {cell: [] for cell in occupied}
    for shape, color in placements:
        if shape:
            for cell in shape:
                if cell in by_cell:
                    by_cell[cell].append((shape, color))

    def cover(remaining, painted):
        if not remaining:
            return painted.copy()
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                for p in shape:
                    painted[p] = color
                result = cover(remaining - shape, painted)
                if result is not None:
                    return result
                for p in shape:
                    del painted[p]
        return None

    painted = cover(occupied, {})
    if painted is None:
        raise ValueError("Nonzero cells cannot be tiled by the demonstrated motifs")
    return [[painted.get((r, c), 0) for c in range(cols)] for r in range(rows)]

