def _components(g, bg):
    h, w = len(g), len(g[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg or (r, c) in seen:
                continue
            color = g[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            rs = [p[0] for p in cells]; cs = [p[1] for p in cells]
            out.append({'color':color, 'cells':cells, 'r0':min(rs), 'r1':max(rs), 'c0':min(cs), 'c1':max(cs)})
    return out

