    r0, c0 = c['r0'], c['c0']
    return frozenset((r-r0, x-c0) for r,x in c['cells'])

def _frame(c):
    """An L-shaped corner divider made of one full edge in each axis."""
    cells = c['cells']; r0,r1,c0,c1 = c['r0'],c['r1'],c['c0'],c['c1']
    h,w = r1-r0+1,c1-c0+1
    if h < 4 or w < 4:
        return False
    bottom = all((r1,x) in cells for x in range(c0,c1+1))
    top = all((r0,x) in cells for x in range(c0,c1+1))
    left = all((y,c0) in cells for y in range(r0,r1+1))
    right = all((y,c1) in cells for y in range(r0,r1+1))
    return (bottom or top) and (left or right)

def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    comps = _components(g, bg)

    # A corner divider frames a reference silhouette. Find a matching object
    # outside it and recolor that object with the divider's color.
    frames = [c for c in comps if _frame(c)]
    for fr in sorted(frames, key=lambda c: -len(c['cells'])):
        inside = [c for c in comps if c is not fr and
                  fr['r0'] <= c['r0'] and c['r1'] <= fr['r1'] and
                  fr['c0'] <= c['c0'] and c['c1'] <= fr['c1']]
        # Prefer the non-divider, non-background silhouette occupying the framed area.
        for ref in sorted(inside, key=lambda c: -len(c['cells'])):
            sh = _shape(ref)
            matches = [c for c in comps if c is not ref and c is not fr and
                       _shape(c) == sh and
                       not (fr['r0'] <= c['r0'] and c['r1'] <= fr['r1'] and
                            fr['c0'] <= c['c0'] and c['c1'] <= fr['c1'])]
            if matches:
                target = min(matches, key=lambda c: (c['r0'], c['c0']))
                for r,x in target['cells']:
                    g[r][x] = fr['color']
                return g

    # In unframed cases, repeated silhouettes identify the upper occurrence;
    # recolor it with the color of the largest remaining object.
    for i, a in enumerate(comps):
        for b in comps[i+1:]:
            if _shape(a) == _shape(b):
                pair = {id(a), id(b)}
                others = [c for c in comps if id(c) not in pair]
                if not others:
                    continue
                swatch = max(others, key=lambda c: len(c['cells']))
                target = min((a,b), key=lambda c: (c['r0'], c['c0']))
                for r,x in target['cells']:
                    g[r][x] = swatch['color']
                return g
    return g

