def transform(grid):
    """Keep the region right of a solid vertical divider; recolor its marks."""
    if not grid or not grid[0]:
        return []
    height, width = len(grid), len(grid[0])
    divider = next(
        (c for c in range(width)
         if all(grid[r][c] == grid[0][c] for r in range(height))
         and grid[0][c] != 0),
        None,
    )
    if divider is None:
        raise ValueError("missing solid vertical divider")
    return [[2 if value != 0 else 0 for value in row[divider + 1:]] for row in grid]

def transform(grid):
    """Keep cells present in both panels separated by a solid horizontal row."""
    if not grid or not grid[0]:
        return []
    h, w = len(grid), len(grid[0])
    divider = next(
        r for r, row in enumerate(grid)
        if row[0] != 0 and all(v == row[0] for v in row)
    )
    top = grid[:divider]
    bottom = grid[divider + 1:]
    if len(top) != len(bottom):
        raise ValueError("panels must have matching heights")
    return [
        [2 if a != 0 and b != 0 else 0 for a, b in zip(upper, lower)]
        for upper, lower in zip(top, bottom)
    ]

def transform(grid):
    """Overlay the two same-sized panels around a solid vertical divider."""
    if not grid or not grid[0]:
        return []
    h, w = len(grid), len(grid[0])
    divider = next(
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] and grid[r][c] != 0 for r in range(h))
    )
    left, right = divider, w - divider - 1
    if left != right:
        raise ValueError("panels must have matching widths")
    return [
        [2 if grid[r][c] != 0 and grid[r][divider + 1 + c] != 0 else 0
         for c in range(left)]
        for r in range(h)
    ]

