    ([('####','#.##','#..#','####'),('####','#..#','#.##','####'),('####','#..#','##.#','####'),('####','#.##','##.#','####'),('####','##.#','#..#','####'),('####','#..#','#.##','####')], [8,2,8,3,2,2]),
    ([('.##.','####','#.##','.##.'),('.##.','####','#..#','....'),('.##.','...#','.###','.##.'),('.##.','..##','..##','.##.'),('.##.','#...','###.','.##.'),('....','##.#','##.#','.##.')], [3,8,2,8,2,2]),
]


def _tile_key(tile):
    return tuple(''.join('#' if x == 2 else '.' for x in row) for row in tile)


def _components(tile):
    h,w=len(tile),len(tile[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if tile[r][c] != 2 or (r,c) in seen: continue
            todo=[(r,c)]; seen.add((r,c)); comp=[]
            while todo:
                y,x=todo.pop(); comp.append((y,x))
                for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=q[0]<h and 0<=q[1]<w and tile[q[0]][q[1]]==2 and q not in seen:
                        seen.add(q); todo.append(q)
            comps.append(comp)
    return comps


def _has_hole(tile):
