    def runs(line, bg):
        out = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color, start = line[i], i
            while i + 1 < len(line) and line[i + 1] == color:
                i += 1
            out.append((color, start, i))
            i += 1
        return out

    # Find matching equal-length colored segments on opposite borders.
    candidates = []
    for orient, first, second in (
        ('h', grid[0], grid[-1]),
        ('v', [grid[r][0] for r in range(h)], [grid[r][-1] for r in range(h)]),
    ):
        for ca, a0, a1 in runs(first, bg):
            for cb, b0, b1 in runs(second, bg):
                if ca == cb and a1 - a0 == b1 - b0:
                    candidates.append((orient, ca, (a0, a1), (b0, b1)))
    if not candidates:
        return [row[:] for row in grid]
    orient, bar, seg_a, seg_b = candidates[0]
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != bar]

    for r, c, color in markers:
        axis = c if orient == 'h' else r
        target = None
        if seg_a[0] <= axis <= seg_a[1]:
            target = seg_b[0] + axis - seg_a[0]
        elif seg_b[0] <= axis <= seg_b[1]:
            target = seg_a[0] + axis - seg_b[0]
        if target is None:
            continue
        if orient == 'h':
